create table public.client (id bigint generated always as identity primary key,company_name varchar(255) not null,registration_number varchar(100),address text,sector_id bigint references public.sector(id) on delete set null,is_active boolean not null default true,source_file text,source_row_number integer,import_batch_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by bigint references public.staff(id) on delete set null);
create table public.client_contact (id bigint generated always as identity primary key,client_id bigint not null references public.client(id) on delete cascade,contact_name varchar(100) not null,contact_email varchar(255),contact_phone varchar(50),contact_designation varchar(100),is_primary boolean not null default false,is_active boolean not null default true,source_file text,source_row_number integer,import_batch_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by bigint references public.staff(id) on delete set null);
