create table public.invoice (id bigint generated always as identity primary key,invoice_no varchar(100),invoice_reference varchar(100),programme_id bigint not null references public.programme(id) on delete restrict,quotation_id bigint references public.quotation(id) on delete set null,purchase_order_id bigint references public.purchase_order(id) on delete set null,client_id bigint not null references public.client(id) on delete restrict,account_id bigint references public.account(id) on delete set null,revenue_type_id bigint references public.revenue_type(id) on delete set null,payment_status_id bigint references public.payment_status(id) on delete set null,payment_terms_id bigint references public.payment_terms(id) on delete set null,payment_method_id bigint references public.payment_method(id) on delete set null,invoice_date date,due_date date,training_start_date date,training_end_date date,amount_excl_tax numeric(18,2),sst_amount numeric(18,2),sst_rate numeric(7,5) default .08,total_incl_tax numeric(18,2),amount_collected numeric(18,2) not null default 0,amount_outstanding numeric(18,2) not null default 0,currency varchar(3) not null default 'MYR',payment_date date,days_outstanding integer,quotation_no_ref varchar(100),po_no_ref varchar(100),is_placeholder boolean not null default false,is_cancelled boolean not null default false,source_file text,source_row_number integer,import_batch_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by bigint references public.staff(id) on delete set null,updated_by bigint references public.staff(id) on delete set null,constraint chk_invoice_dates check(training_end_date is null or training_start_date is null or training_end_date>=training_start_date),constraint chk_invoice_sst_rate check(sst_rate between 0 and 1));
create index idx_invoice_programme on public.invoice(programme_id); create index idx_invoice_client on public.invoice(client_id); create index idx_invoice_due_date on public.invoice(due_date); create index idx_invoice_status on public.invoice(payment_status_id); create index idx_invoice_import_batch on public.invoice(import_batch_id); create index idx_invoice_real_no on public.invoice(invoice_no) where invoice_no is not null and invoice_no<>'';
create table public.payment (id bigint generated always as identity primary key,payment_reference varchar(100),invoice_id bigint references public.invoice(id) on delete set null,programme_id bigint references public.programme(id) on delete set null,client_id bigint references public.client(id) on delete set null,payment_date date,amount numeric(18,2) not null default 0,sst_amount numeric(18,2) not null default 0,total_amount numeric(18,2) not null default 0,currency varchar(3) not null default 'MYR',amount_allocated numeric(18,2) not null default 0,amount_unallocated numeric(18,2) not null default 0,payment_method_id bigint references public.payment_method(id) on delete set null,payment_status_id bigint references public.payment_status(id) on delete set null,received_by_id bigint references public.staff(id) on delete set null,bank_reference varchar(100),cheque_no varchar(100),transaction_id varchar(150),notes text,source_file text,source_row_number integer,import_batch_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by bigint references public.staff(id) on delete set null,updated_by bigint references public.staff(id) on delete set null,constraint chk_payment_amount check(amount>=0),constraint chk_payment_alloc check(amount_allocated>=0 and amount_unallocated>=0));
create index idx_payment_invoice on public.payment(invoice_id); create index idx_payment_programme on public.payment(programme_id); create index idx_payment_date on public.payment(payment_date); create index idx_payment_status on public.payment(payment_status_id);

