create table public.training_stat (id bigint generated always as identity primary key,programme_id bigint not null references public.programme(id) on delete restrict,training_type_id bigint references public.training_type(id) on delete set null,training_date date,training_name varchar(500),company_name varchar(255),training_category varchar(100),duration_days numeric(5,2),domain_code varchar(50),domain_name varchar(100),workshop_count integer default 0,training_count integer default 0,total_count integer default 0,bumiputera_count integer default 0,non_bumiputera_count integer default 0,total_charges_excl_tax numeric(18,2),sst_amount numeric(18,2),final_charges_incl_tax numeric(18,2),currency varchar(3) default 'MYR',source_file text,source_row_number integer,import_batch_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by bigint references public.staff(id) on delete set null,updated_by bigint references public.staff(id) on delete set null,constraint chk_training_counts check(workshop_count>=0 and training_count>=0 and total_count>=0 and bumiputera_count>=0 and non_bumiputera_count>=0));
