-- 006 triggers/functions
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['profiles','account_type','staff_role','sector','training_type','payment_method','payment_status','quotation_type','quotation_status','programme_status','project_status','opportunity_status','action_item_status','payment_terms','speed_to_market','programme_category','service_type','revenue_type','account','staff','client','client_contact','programme','quotation','purchase_order','invoice','payment','opportunity','action_item','training_stat','participant','import_batch'] loop execute format('drop trigger if exists %I on public.%I',t||'_updated_at',t); execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_updated_at',t); end loop; end $$;
create or replace function public.fn_days_outstanding(p_due_date date,p_paid boolean default false) returns integer language sql stable as $$ select case when p_due_date is null or p_paid then null else current_date-p_due_date end $$;
create or replace function public.fn_weighted_forecast(p_forecast numeric,p_probability numeric) returns numeric language sql immutable as $$ select case when p_forecast is null or p_probability is null then null else round(p_forecast*greatest(least(p_probability,100),0)/100,2) end $$;
create or replace function public.fn_calc_sst(p_base_amount numeric,p_sst_rate numeric default .08) returns numeric language sql immutable as $$ select case when p_base_amount is null or p_sst_rate is null then null else round(p_base_amount*p_sst_rate,2) end $$;
create or replace function public.fn_calc_total_incl_sst(p_base_amount numeric,p_sst_amount numeric) returns numeric language sql immutable as $$ select case when p_base_amount is null then null else p_base_amount+coalesce(p_sst_amount,0) end $$;
create or replace function public.fn_refresh_invoice(p_invoice_id bigint) returns void language plpgsql security definer set search_path=public as $$ declare v_collected numeric; begin select coalesce(sum(coalesce(amount,0)),0) into v_collected from public.payment p left join public.payment_status ps on ps.id=p.payment_status_id where p.invoice_id=p_invoice_id and coalesce(ps.code,'') in ('PAID','COMPLETED','SUCCESS'); update public.invoice i set amount_collected=least(v_collected,coalesce(i.total_incl_tax,i.amount_excl_tax,0)),amount_outstanding=greatest(coalesce(i.total_incl_tax,i.amount_excl_tax,0)-least(v_collected,coalesce(i.total_incl_tax,i.amount_excl_tax,0)),0),days_outstanding=public.fn_days_outstanding(i.due_date,v_collected>=coalesce(i.total_incl_tax,i.amount_excl_tax,0)) where i.id=p_invoice_id; end; $$;
create or replace function public.trg_payment_refresh_invoice() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='DELETE' then perform public.fn_refresh_invoice(old.invoice_id); else perform public.fn_refresh_invoice(new.invoice_id); if tg_op='UPDATE' and old.invoice_id is distinct from new.invoice_id then perform public.fn_refresh_invoice(old.invoice_id); end if; end if; return coalesce(new,old); end; $$;
drop trigger if exists payment_refresh_invoice on public.payment; create trigger payment_refresh_invoice after insert or update or delete on public.payment for each row execute function public.trg_payment_refresh_invoice();
create or replace function public.fn_refresh_programme(p_programme_id bigint) returns void language plpgsql security definer set search_path=public as $$ begin update public.programme p set total_revenue_excl_tax=coalesce((select sum(i.amount_excl_tax) from public.invoice i where i.programme_id=p.id and not i.is_cancelled and not i.is_placeholder),0),total_sst_amount=coalesce((select sum(i.sst_amount) from public.invoice i where i.programme_id=p.id and not i.is_cancelled and not i.is_placeholder),0),total_revenue_incl_tax=coalesce((select sum(i.total_incl_tax) from public.invoice i where i.programme_id=p.id and not i.is_cancelled and not i.is_placeholder),0),total_collected=coalesce((select sum(i.amount_collected) from public.invoice i where i.programme_id=p.id and not i.is_cancelled and not i.is_placeholder),0),total_outstanding=coalesce((select sum(i.amount_outstanding) from public.invoice i where i.programme_id=p.id and not i.is_cancelled and not i.is_placeholder),0) where p.id=p_programme_id; end; $$;
create or replace function public.trg_invoice_refresh_programme() returns trigger language plpgsql security definer set search_path=public as $$ begin perform public.fn_refresh_programme(coalesce(new.programme_id,old.programme_id)); return coalesce(new,old); end; $$;
drop trigger if exists invoice_refresh_programme on public.invoice; create trigger invoice_refresh_programme after insert or update or delete on public.invoice for each row execute function public.trg_invoice_refresh_programme();
create or replace function public.fn_programme_completeness(p_programme_id bigint) returns numeric language plpgsql security definer set search_path=public as $$ declare n int:=0; s int:=0; begin select count(*) into n from public.quotation where programme_id=p_programme_id; if n>0 then s:=s+1; end if; select count(*) into n from public.purchase_order where programme_id=p_programme_id; if n>0 then s:=s+1; end if; select count(*) into n from public.invoice where programme_id=p_programme_id and not is_placeholder and not is_cancelled; if n>0 then s:=s+1; end if; select count(*) into n from public.payment where programme_id=p_programme_id; if n>0 then s:=s+1; end if; select count(*) into n from public.training_stat where programme_id=p_programme_id; if n>0 then s:=s+1; end if; select count(*) into n from public.participant where programme_id=p_programme_id; if n>0 then s:=s+1; end if; select count(*) into n from public.invoice where programme_id=p_programme_id and coalesce(amount_excl_tax,0)>0; if n>0 then s:=s+1; end if; select count(*) into n from public.programme where id=p_programme_id and pic_id is not null; if n>0 then s:=s+1; end if; insert into public.completeness_score(programme_id,overall_score,overall_status,evaluated_at) values(p_programme_id,round(s*12.5,2),case when s=8 then 'COMPLETE' when s>=6 then 'PARTIAL' else 'INCOMPLETE' end,now()) on conflict(programme_id) do update set overall_score=excluded.overall_score,overall_status=excluded.overall_status,evaluated_at=now(); return round(s*12.5,2); end; $$;
alter table public.account add constraint fk_account_created_by foreign key(created_by) references public.staff(id) on delete set null;
alter table public.profiles add constraint fk_profile_staff foreign key(staff_id) references public.staff(id) on delete set null;

-- 007 Auth/RLS
create or replace function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and is_active $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role()='admin',false) $$;
create or replace function public.is_staff_or_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_app_role() in ('admin','staff'),false) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',split_part(coalesce(new.email,''),'@',1)),'staff') on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
do $$ declare t text; begin foreach t in array array['profiles','account_type','staff_role','sector','training_type','payment_method','payment_status','quotation_type','quotation_status','programme_status','project_status','opportunity_status','action_item_status','payment_terms','speed_to_market','programme_category','service_type','revenue_type','account','staff','client','client_contact','programme','quotation','purchase_order','invoice','payment','opportunity','action_item','training_stat','participant','source_file','import_batch','stg_import_row','data_conflict','completeness_score','staff_alias','client_alias','audit_log','audit_history'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['account_type','staff_role','sector','training_type','payment_method','payment_status','quotation_type','quotation_status','programme_status','project_status','opportunity_status','action_item_status','payment_terms','speed_to_market','programme_category','service_type','revenue_type','account','staff','client','client_contact','programme','quotation','purchase_order','invoice','payment','opportunity','action_item','training_stat','participant','source_file','import_batch','stg_import_row','data_conflict','completeness_score','staff_alias','client_alias','audit_history'] loop execute format('create policy %I_read on public.%I for select to authenticated using(auth.uid() is not null)',t,t); execute format('create policy %I_insert on public.%I for insert to authenticated with check(public.is_staff_or_admin())',t,t); execute format('create policy %I_update on public.%I for update to authenticated using(public.is_staff_or_admin()) with check(public.is_staff_or_admin())',t,t); execute format('create policy %I_delete on public.%I for delete to authenticated using(public.is_admin())',t,t); end loop; end $$;
create policy profiles_self_or_admin_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy profiles_self_or_admin_update on public.profiles for update to authenticated using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
create policy profiles_admin_insert on public.profiles for insert to authenticated with check(public.is_admin() or id=auth.uid());
create policy profiles_admin_delete on public.profiles for delete to authenticated using(public.is_admin());
create policy audit_log_admin_read on public.audit_log for select to authenticated using(public.is_admin());
create policy audit_log_staff_insert on public.audit_log for insert to authenticated with check(public.is_staff_or_admin());

-- 008 views
create or replace view public.v_r1_income_statement as select i.id invoice_id,i.invoice_no,i.invoice_date,i.due_date,public.fn_days_outstanding(i.due_date,i.amount_outstanding<=0) days_outstanding,p.id programme_id,p.programme_code,p.title programme_title,c.id client_id,c.company_name client_name,a.code account_code,a.name account_name,rt.code revenue_type_code,rt.name revenue_type_name,i.amount_excl_tax,i.sst_amount,i.sst_rate,i.total_incl_tax,i.amount_collected,i.amount_outstanding,ps.code payment_status_code,ps.name payment_status_name,i.payment_date,pm.code payment_method_code,pm.name payment_method_name,pt.code payment_terms_code,pt.name payment_terms_name,i.quotation_no_ref,i.po_no_ref,i.training_start_date,i.training_end_date,am.full_name account_manager,pic.full_name pic_name,i.is_placeholder,i.is_cancelled,i.source_file,i.source_row_number from public.invoice i left join public.programme p on p.id=i.programme_id left join public.client c on c.id=i.client_id left join public.account a on a.id=i.account_id left join public.revenue_type rt on rt.id=i.revenue_type_id left join public.payment_status ps on ps.id=i.payment_status_id left join public.payment_method pm on pm.id=i.payment_method_id left join public.payment_terms pt on pt.id=i.payment_terms_id left join public.staff am on am.id=p.account_manager_id left join public.staff pic on pic.id=p.pic_id where not i.is_cancelled;
create or replace view public.v_r2_training_stats as select p.id programme_id,p.programme_code,p.title programme_title,c.company_name client_name,tt.name training_type_name,pc.name programme_category_name,p.start_date,p.end_date,p.duration_days,p.no_of_pax,ts.training_date,ts.training_name,ts.company_name training_company,ts.training_category,ts.domain_code,ts.domain_name,ts.workshop_count,ts.training_count,ts.total_count,ts.bumiputera_count,ts.non_bumiputera_count,ts.total_charges_excl_tax,ts.sst_amount training_sst,ts.final_charges_incl_tax,p.total_revenue_excl_tax,p.total_sst_amount,p.total_revenue_incl_tax,p.total_collected,p.total_outstanding,ps.name programme_status_name,am.full_name account_manager,pic.full_name pic_name from public.programme p left join public.client c on c.id=p.client_id left join public.training_type tt on tt.id=p.training_type_id left join public.programme_category pc on pc.id=p.programme_category_id left join public.programme_status ps on ps.id=p.programme_status_id left join public.staff am on am.id=p.account_manager_id left join public.staff pic on pic.id=p.pic_id left join public.training_stat ts on ts.programme_id=p.id;
create or replace view public.v_r3_funnel_pipeline as select o.id opportunity_id,o.opportunity_code,c.company_name client_name,o.project_title,o.project_description,o.opportunity_type,os.name opportunity_status,os.code opportunity_status_code,stm.name speed_to_market,stm.quarter,stm.year,s.name sector_name,o.forecast_value,o.probability_percentage,coalesce(o.weighted_value,public.fn_weighted_forecast(o.forecast_value,o.probability_percentage)) weighted_value,o.secured_value,o.currency,o.expected_close_date,o.actual_close_date,o.po_date,o.po_value,o.is_government,o.is_private,o.is_interco,o.remarks,o.sector_remarks,am.full_name account_manager,sm.full_name salesman,p.id programme_id,p.programme_code linked_programme,o.source_file,o.source_row_number from public.opportunity o left join public.client c on c.id=o.client_id left join public.opportunity_status os on os.id=o.opportunity_status_id left join public.speed_to_market stm on stm.id=o.speed_to_market_id left join public.sector s on s.id=o.sector_id left join public.staff am on am.id=o.account_manager_id left join public.staff sm on sm.id=o.salesman_id left join public.programme p on p.id=o.programme_id;
create or replace view public.v_programme_completeness as select p.id programme_id,p.programme_code,p.title,c.company_name client_name,ps.name programme_status,cs.quotation_score,cs.po_score,cs.invoice_score,cs.payment_score,cs.delivery_score,cs.participant_score,cs.charges_score,cs.pic_score,cs.overall_score,cs.overall_status,cs.missing_components,cs.na_components,cs.evaluated_at,p.total_revenue_excl_tax,p.total_revenue_incl_tax,p.total_collected,p.total_outstanding,p.start_date,p.end_date,p.duration_days,p.no_of_pax,am.full_name account_manager,pic.full_name pic_name from public.programme p left join public.client c on c.id=p.client_id left join public.programme_status ps on ps.id=p.programme_status_id left join public.completeness_score cs on cs.programme_id=p.id left join public.staff am on am.id=p.account_manager_id left join public.staff pic on pic.id=p.pic_id;
create or replace view public.v_financial_dashboard as select 'REVENUE' metric_category,'Total Revenue (excl SST)' metric_name,coalesce(sum(amount_excl_tax),0)::numeric metric_value,count(*) record_count from public.invoice where not is_cancelled and not is_placeholder union all select 'REVENUE','Total Revenue (incl SST)',coalesce(sum(total_incl_tax),0),count(*) from public.invoice where not is_cancelled and not is_placeholder union all select 'COLLECTION','Total Collected',coalesce(sum(amount_collected),0),count(*) from public.invoice where not is_cancelled and not is_placeholder union all select 'COLLECTION','Total Outstanding',coalesce(sum(amount_outstanding),0),count(*) from public.invoice where not is_cancelled and not is_placeholder union all select 'OVERDUE','Overdue Amount',coalesce(sum(amount_outstanding),0),count(*) from public.invoice where not is_cancelled and not is_placeholder and due_date<current_date and amount_outstanding>0 union all select 'FUNNEL','Total Forecast Value',coalesce(sum(forecast_value),0),count(*) from public.opportunity union all select 'FUNNEL','Total Weighted Forecast',coalesce(sum(coalesce(weighted_value,public.fn_weighted_forecast(forecast_value,probability_percentage))),0),count(*) from public.opportunity;
create or replace view public.v_action_item_dashboard as select ai.id action_item_id,ai.action_item_code,c.company_name client_name,p.title programme_title,o.project_title opportunity_title,ai.service,ai.action_description,ai.person_in_charge,ai.person_email,ai.due_date,ai.completed_date,ai.aging_days,ai.priority,ais.name status_name,ais.code status_code,ai.potential_revenue,ai.currency,ai.notes,st.full_name assigned_to,ai.created_at,ai.updated_at from public.action_item ai left join public.client c on c.id=ai.client_id left join public.programme p on p.id=ai.programme_id left join public.opportunity o on o.id=ai.opportunity_id left join public.action_item_status ais on ais.id=ai.action_item_status_id left join public.staff st on st.id=ai.assigned_to_id;
create or replace view public.v_payment_collection as select py.id payment_id,py.payment_reference,i.invoice_no,i.invoice_date,prog.id programme_id,prog.title programme_title,c.company_name client_name,py.payment_date,py.amount,py.sst_amount,py.total_amount,py.currency,py.amount_allocated,py.amount_unallocated,pm.name payment_method,ps.name payment_status,rb.full_name received_by,py.bank_reference,py.cheque_no,py.transaction_id,py.notes from public.payment py left join public.invoice i on i.id=py.invoice_id left join public.programme prog on prog.id=py.programme_id left join public.client c on c.id=py.client_id left join public.payment_method pm on pm.id=py.payment_method_id left join public.payment_status ps on ps.id=py.payment_status_id left join public.staff rb on rb.id=py.received_by_id;
create or replace view public.v_staff_performance as select s.id staff_id,s.full_name,s.email,sr.name role_name,count(distinct p.id) programmes_managed,count(distinct q.id) quotations_prepared,count(distinct o.id) opportunities_owned,count(distinct ai.id) action_items_assigned,coalesce(sum(distinct p.total_revenue_excl_tax),0) total_revenue_managed,coalesce(sum(distinct p.total_collected),0) total_collected_managed from public.staff s left join public.staff_role sr on sr.id=s.role_id left join public.programme p on p.account_manager_id=s.id left join public.quotation q on q.account_manager_id=s.id left join public.opportunity o on o.account_manager_id=s.id left join public.action_item ai on ai.assigned_to_id=s.id where s.is_active group by s.id,s.full_name,s.email,sr.name;

-- 009 indexes/realtime
create index if not exists idx_programme_pic on public.programme(pic_id); create index if not exists idx_programme_account_manager on public.programme(account_manager_id); create index if not exists idx_invoice_due_outstanding on public.invoice(due_date,amount_outstanding) where amount_outstanding>0; create index if not exists idx_payment_reference on public.payment(payment_reference); create index if not exists idx_opportunity_salesman on public.opportunity(salesman_id); create index if not exists idx_action_item_due_status on public.action_item(due_date,action_item_status_id); create index if not exists idx_participant_email on public.participant(email); create index if not exists idx_import_status on public.import_batch(status); create index if not exists idx_conflict_status on public.data_conflict(resolution);
alter publication supabase_realtime add table public.programme; alter publication supabase_realtime add table public.opportunity; alter publication supabase_realtime add table public.action_item; alter publication supabase_realtime add table public.invoice; alter publication supabase_realtime add table public.payment;

